def parse_latencies(lines):
    """Yield the latency in milliseconds of each access-log line, e.g. 'GET /users/42 200 35ms' gives 35."""
    for line in lines:
        yield int(line.split()[-1].removesuffix("ms"))


def summarize_latencies(lines):
    """Return {"count": n, "mean_ms": average, "max_ms": slowest} for a stream of access-log lines."""
    latencies = parse_latencies(lines)
    count = sum(1 for _ in latencies)
    total = sum(latencies)
    return {
        "count": count,
        "mean_ms": round(total / count, 2) if count else 0.0,
        "max_ms": max(latencies, default=0),
    }

