def parse_latencies(lines):
    for line in lines:
        yield int(line.split()[-1].removesuffix("ms"))


def summarize_latencies(lines):
    # One pass: a generator can be read only once, so collect all three numbers while going through it
    count = total = slowest = 0
    for latency in parse_latencies(lines):
        count += 1
        total += latency
        slowest = max(slowest, latency)
    return {
        "count": count,
        "mean_ms": round(total / count, 2) if count else 0.0,
        "max_ms": slowest,
    }
